{
 "id": "najdi-door-panel-rows",
 "name": "Najdi Cut Row Step",
 "idea": "A wide dark earth surface with fine plaster grain carries one thin band of small equal triangle cuts along the top edge, a single red mark steps from cut to cut, right to left, leaving a faint warm trace, and a soft daylight slowly drifts across the wall.",
 "use": [
  "hero",
  "loading",
  "onboarding-slide",
  "paywall-plan"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
float tri(vec2 p,float r){const float k=1.7320508;p.x=abs(p.x)-r;p.y=p.y+r/k;if(p.x+k*p.y>0.0)p=vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;p.x-=clamp(p.x,-2.0*r,0.0);return -length(p)*sign(p.y);}
void main(){
vec2 r=u_resolution;vec2 p=(gl_FragCoord.xy-0.5*r)/r.y;float px=1.5/r.y;float t=u_time;
float ax=0.5*r.x/r.y;
float cs=0.052;
float yb=0.5-0.085;
float gx=p.x/cs;float ci=floor(gx);
vec2 lc=vec2((fract(gx)-0.5)*cs,p.y-yb);
float hc=floor(ax/cs);
float N=2.0*hc;
float tt=t/1.8;float f=fract(tt);
float pos=floor(tt)+smoothstep(0.0,0.55,f);
float head=hc+2.0-mod(pos,N+6.0);
float d=tri(lc,cs*0.27);
float tm=1.0-smoothstep(-px,px,d);
float dd=ci-head;
float w=1.0-smoothstep(0.0,0.7,abs(dd));
float tr=step(0.5,dd)*exp(-dd*0.6)*0.45;
float acc=max(w,tr);
vec3 col=u_c0*(0.9+0.1*smoothstep(-0.6,0.5,p.y));
col*=0.96+0.08*n(p*1.2+vec2(t*0.1,-t*0.07));
float gr=n(gl_FragCoord.xy*0.7)-0.5;
float tw=n(vec2(p.x*7.0+t*0.05,p.y*90.0))-0.5;
col+=u_c1*(gr*0.025+tw*0.012);
float lx=0.75*cos(t*0.4)*ax;
float q=(p.x-lx)/(0.45+0.35*ax);
float lg=exp(-q*q)*(0.75+0.25*smoothstep(-0.5,0.5,p.y));
col*=0.88+0.26*lg;
col+=u_c3*0.06*lg;
float ay=abs(p.y-yb);
float strip=1.0-smoothstep(cs*0.62-px,cs*0.62+px,ay);
col=mix(col,mix(u_c0,u_c3,0.18)*(0.9+0.15*lg),strip*0.5);
float ln=1.0-smoothstep(0.0012,0.0012+px,abs(ay-cs*0.62));
col=mix(col,u_c1,ln*0.16);
vec3 cut=u_c0*0.45;
vec3 tc=mix(cut,u_c2,acc);
col=mix(col,tc,tm);
float hx=(head+0.5)*cs;
col+=u_c2*0.12*exp(-length(vec2(p.x-hx,(p.y-yb)*1.4))*10.0);
vec2 v=p*vec2(0.6,0.8);
col*=1.0-0.12*dot(v,v);
gl_FragColor=vec4(col,1.0);}
",
 "colors": [
  "#3b2a1e",
  "#f3ebdd",
  "#a8432f",
  "#b98a5e"
 ],
 "reduced": {
  "kind": "fade",
  "at": 9,
  "ms": 400,
  "note": "The earth surface fades in with soft light on the left, its row of triangle cuts along the top and one red cut resting near the right."
 },
 "cardIds": [
  "najdi-painted-doors",
  "najdi-mud-architecture"
 ],
 "lensIds": [
  "najdi"
 ],
 "culturalNotes": "Follows Najdi architecture, the mud-brick building tradition of the builders and families of Najd in central Arabia, and the painted wooden doors that belong to it. It borrows the rule of a large plain earth mass under one strict row of small equal triangular cuts. A thin pale band marks the change of section. The painted door red is the only accent, with mud brick ochre and lime plaster cream kept to a hint. The mark steps right to left, one equal repeat at a time, so it reads in the direction of Arabic text, and a slow soft light moves over the plain wall. It draws no door, frame, building or heritage site and gives the triangles no meaning. At-Turaif District in ad-Dir'iyah is inscribed by UNESCO as a World Heritage site, and this shader is not endorsed by the site.",
 "styles": [
  "gulf-arabic-first"
 ]
}
