```json
{
 "id": "model-rail-loop",
 "name": "Station Tick Loop",
 "idea": "A flat closed loop of fine ink hairline dashes sits centred on a cream ground with eight evenly spaced station ticks, and a short red segment of three parallel hairlines eases from tick to tick, pausing two seconds at each while the tick ahead turns from green to red during the wait, one lap every 16 seconds.",
 "use": [
  "progress",
  "stepper",
  "loading",
  "empty-state"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float px=1.5/u_resolution.y;
float a=u_resolution.x/u_resolution.y;
float PI=3.14159265;
float r=0.07;
float Lh=max(0.39*a-r,0.06);
float sd=length(vec2(max(abs(p.x)-Lh,0.0),p.y))-r;
float P=4.0*Lh+2.0*PI*r;
float s=0.0;
if(p.x>Lh){s=2.0*Lh+r*(atan(p.y,p.x-Lh)+0.5*PI);}
else if(p.x<-Lh){s=4.0*Lh+PI*r+r*mod(atan(p.y,p.x+Lh)-0.5*PI,2.0*PI);}
else if(p.y<0.0){s=p.x+Lh;}
else{s=2.0*Lh+PI*r+Lh-p.x;}
float d=sd+(n(vec2(s*70.0,3.1))-0.5)*0.0014;
float lw=0.0011;
float ink=0.8+0.2*n(gl_FragCoord.xy*0.18);
float drift=n(p*4.0+vec2(u_time*0.12,u_time*0.05));
vec3 col=mix(u_c0,u_c3,0.05*drift);
col=mix(col,u_c1,0.02*n(gl_FragCoord.xy*0.012+7.0));
float N=8.0;
float st=P/N;
float tt=u_time/2.0;
float k=floor(tt);
float f=fract(tt);
float x=clamp(f/0.46,0.0,1.0);
float e=x*x*(3.0-2.0*x);
e=1.0-(1.0-e)*(1.0-e);
float head=(k+e)*st;
float segL=st*0.32;
float dc=mod(head-s-0.5*segL+0.5*P,P)-0.5*P;
float glow=exp(-dc*dc/0.006-d*d/0.0016);
col=mix(col,u_c2,0.14*glow);
float per=P/floor(P/0.013);
float dash=1.0-smoothstep(per*0.5-px,per*0.5,mod(s,per));
float line=1.0-smoothstep(lw,lw+px,abs(d));
float dh=mod(head-s,P);
float seg=smoothstep(0.0,px,dh)*(1.0-smoothstep(segL-px,segL,dh));
col=mix(col,u_c1,line*dash*0.78*ink*(1.0-seg));
float m=mod(s+0.5*st,st)-0.5*st;
float idx=mod(floor((s+0.5*st)/st),N);
float td=length(max(vec2(abs(m),abs(d))-vec2(0.0,0.022),0.0));
float tick=1.0-smoothstep(lw,lw+px,td);
float isA=1.0-step(0.5,abs(idx-mod(k+2.0,N)));
float wait=smoothstep(0.5,0.6,f)*(1.0-smoothstep(0.93,1.0,f));
col=mix(col,mix(u_c3,u_c2,isA*wait),tick*0.9*ink);
float la=1.0-smoothstep(lw,lw+px,min(abs(d),abs(abs(d)-0.0055)));
col=mix(col,u_c2,la*seg*0.92*ink);
col+=(h(floor(gl_FragCoord.xy)+3.7)-0.5)*0.035;
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#ece7d9",
